// ---------------------------------------------------------------
// Valida la entrada y construye la petición para el modelo.
// Acepta datos del Webhook (body.texto) o del Manual Trigger (texto).
// ---------------------------------------------------------------
const config = $('Configuración').first().json;
const entrada = $input.first().json;
const datos = entrada.body && typeof entrada.body === 'object' ? entrada.body : entrada;

const texto = String(datos.texto || '').replace(/\s+/g, ' ').trim();
const fuente = String(datos.fuente || 'manual').slice(0, 100);
const maximo = Number(config.maxInputChars) || 6000;
const categorias = String(config.categorias).split(',').map((c) => c.trim()).filter(Boolean);

if (texto.length < 20) {
  return [{ json: { valido: false, error: 'El campo "texto" es obligatorio y debe tener al menos 20 caracteres.' } }];
}

const textoRecortado = texto.slice(0, maximo);
const instrucciones = [
  'Eres un asistente que organiza información personal.',
  'Analiza el texto del usuario y responde SOLO con un objeto JSON válido, sin texto adicional,',
  'con exactamente estas claves:',
  `- "categoria": una de [${categorias.join(', ')}]`,
  '- "titulo": título breve de máximo 80 caracteres',
  '- "resumen": resumen en español de máximo 3 frases',
  '- "puntos_clave": lista de 1 a 5 frases cortas',
  '- "etiquetas": lista de 1 a 5 palabras clave en minúsculas',
  'No inventes datos que no estén en el texto.',
].join('\n');

return [{ json: {
  valido: true,
  texto: textoRecortado,
  recortado: texto.length > maximo,
  fuente,
  categorias,
  requestBody: {
    model: config.model,
    temperature: 0.2,
    messages: [
      { role: 'system', content: instrucciones },
      { role: 'user', content: textoRecortado },
    ],
  },
} }];

// ---------------------------------------------------------------
// MODELO SIMULADO: reglas por palabras clave, NO es inteligencia artificial.
// Devuelve el mismo formato que la API compatible con OpenAI para que
// el resto del workflow funcione igual sin proveedor configurado.
// ---------------------------------------------------------------
const { texto, categorias } = $input.first().json;
const minusculas = texto.toLowerCase();
const PISTAS = {
  trabajo: ['reunión', 'cliente', 'proyecto', 'entrega', 'equipo', 'informe'],
  estudio: ['curso', 'aprender', 'examen', 'tutorial', 'estudiar', 'clase'],
  finanzas: ['pago', 'factura', 'presupuesto', 'ahorro', 'gasto'],
  salud: ['ejercicio', 'médico', 'dormir', 'dieta', 'salud'],
  ideas: ['idea', 'podría', 'proponer', 'mejorar'],
};
const categoria = Object.keys(PISTAS).find((c) => categorias.includes(c) && PISTAS[c].some((p) => minusculas.includes(p)))
  || (categorias.includes('referencia') ? 'referencia' : categorias[0]);

const frases = texto.split(/(?<=[.!?])\s+/).filter((f) => f.length > 10);
const palabras = [...new Set(minusculas.match(/[a-záéíóúñ]{6,}/g) || [])].slice(0, 4);

const contenido = {
  categoria,
  titulo: (frases[0] || texto).slice(0, 80),
  resumen: frases.slice(0, 2).join(' ') || texto.slice(0, 200),
  puntos_clave: frases.slice(0, 3).map((f) => f.slice(0, 120)),
  etiquetas: palabras,
};

return [{ json: {
  model: 'simulado',
  choices: [{ index: 0, message: { role: 'assistant', content: JSON.stringify(contenido) } }],
} }];

// ---------------------------------------------------------------
// La salida de un modelo es texto NO confiable: se extrae el JSON,
// se valida su estructura y se normalizan los campos antes de guardar.
// ---------------------------------------------------------------
const preparado = $('Preparar solicitud').first().json;
const respuesta = $input.first().json;
const contenido = String(respuesta.choices?.[0]?.message?.content || '');
const modelo = String(respuesta.model || 'desconocido');

function extraerJson(texto) {
  const limpio = texto.replace(/```(?:json)?/gi, '').trim();
  const inicio = limpio.indexOf('{');
  const fin = limpio.lastIndexOf('}');
  if (inicio === -1 || fin <= inicio) throw new Error('La respuesta no contiene un objeto JSON');
  return JSON.parse(limpio.slice(inicio, fin + 1));
}

const lista = (v, max) => (Array.isArray(v) ? v : [])
  .map((x) => String(x).trim()).filter(Boolean).slice(0, max);

const errores = [];
let datos = {};
try {
  datos = extraerJson(contenido);
} catch (error) {
  errores.push(`JSON no válido: ${error.message}`);
}

let categoria = String(datos.categoria || '').toLowerCase().trim();
if (!preparado.categorias.includes(categoria)) {
  if (categoria) errores.push(`Categoría desconocida "${categoria}"`);
  categoria = 'referencia';
}
const resumen = String(datos.resumen || '').trim().slice(0, 600);
if (!resumen) errores.push('Falta el resumen');
const puntos = lista(datos.puntos_clave, 5);
if (puntos.length === 0) errores.push('Faltan los puntos clave');

return [{ json: {
  valido: errores.length === 0,
  errores: errores.join('; '),
  id: 'K-' + Date.now().toString(36).toUpperCase(),
  fecha: $now.toFormat('yyyy-MM-dd HH:mm'),
  fuente: preparado.fuente,
  categoria,
  titulo: String(datos.titulo || '').trim().slice(0, 80) || preparado.texto.slice(0, 80),
  resumen,
  puntos_clave: puntos.join(' | '),
  etiquetas: lista(datos.etiquetas, 5).map((e) => e.toLowerCase()).join(', '),
  modelo,
  estado: errores.length === 0 ? 'ok' : 'revisar',
  texto_original: preparado.texto.slice(0, 1000),
} }];

// Respuesta final (también es la respuesta HTTP del Webhook).
const r = $('Validar respuesta').first().json;
return [{ json: {
  ok: true,
  id: r.id,
  estado: r.estado,
  categoria: r.categoria,
  titulo: r.titulo,
  resumen: r.resumen,
  puntos_clave: r.puntos_clave.split(' | ').filter(Boolean),
  etiquetas: r.etiquetas.split(', ').filter(Boolean),
  errores: r.errores || undefined,
} }];
